// Nike Swoosh (white, transparent PNG 1600x576) supplied by the CD.
// Fills every empty logo slot and the hero emblem slots; a Logo/Emblem upload in the panel still overrides it.
export const NF_LOGO_SLOT =
    "data:image/png;base64,"

export function nfCss(onCanvas) {
    if (!onCanvas) return NF_CSS
    return (
        NF_CSS.split("@media /*W*/").join("@container nfx ") +
        ".nfx{container:nfx/inline-size}" +
        NF_CANVAS_CSS
    )
}

const escText = (s) =>
    String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
const escAttr = (s) => escText(s).replace(/"/g, "&quot;")

export function renderMarkup(markup, texts, props, images) {
    const byKey = {}
    for (const t of texts) byKey[t.k] = t
    return markup.replace(/\{\{(img:)?([\w]+)\}\}/g, (m, isImg, k) => {
        if (isImg)
            return escAttr(
                (images && images[k]) ||
                    (props.images && props.images[k]) ||
                    NF_IMG[k] ||
                    (k === "logo" || k === "emblem" ? NF_LOGO_SLOT : "")
            )
        const t = byKey[k]
        if (!t) return ""
        const g = props[t.g]
        const v = g && g[k] != null ? g[k] : t.d
        return t.a ? escAttr(v) : escText(v)
    })
}

export function textControls(texts) {
    const groups = {}
    for (const t of texts) {
        if (!groups[t.g])
            groups[t.g] = {
                type: ControlType.Object,
                title: t.gt,
                controls: {},
            }
        groups[t.g].controls[t.k] = {
            type: ControlType.String,
            title: t.l,
            defaultValue: t.d,
            displayTextArea: t.d.length > 48,
        }
    }
    return groups
}
